import { Injectable } from "@angular/core";
import { HttpClient, HttpHeaders } from "@angular/common/http";
import { Observable } from "rxjs";
import

@Injectable({
  providedIn: "root",
})
export class ContactService {
  private apiUrl = "http://localhost:8080/api/contacts";

  constructor(private http: HttpClient) {}

  // Public contact form
  sendMessage(contact: any): Observable<any> {
    return this.http.post("http://localhost:8080/api/contacts", contact);
  }

  // Admin - get all messages
  getContacts() {
    return this.http.get<any[]>("http://localhost:8080/api/contacts");
  }

  deleteContact(id: number) {
    return this.http.delete(`http://localhost:8080/api/contacts/${id}`);
  }
}
